  "主 Codex 请使用顶部的「重启 Codex」。": "For the main Codex, use Restart Codex at the top.",
  "主 Codex 请使用侧栏的「停止 Codex」。": "For the main Codex, use Stop Codex in the sidebar.",
  "结束此 Codex 实例": "Stop this Codex instance",
