  "找回、继续各 Agent 的本地会话": "Find and resume local agent sessions",
  "Codex 供应商": "Codex providers",
  "Codex 还没登录 ChatGPT。在 Codex 里登录，或添加一个 API 供应商并设为当前。": "Codex isn't signed in to ChatGPT. Sign in inside Codex, or add an API provider and make it current.",
  "供应商配置切换已关闭，Codex++ 不会改动 Codex 的连接。在「连接与供应商」里打开。": "Provider config switching is off, so Codex++ won't change how Codex connects. Turn it on under Connection & providers.",
  "当前供应商的模型请求测试通过。": "The current provider passed the model request test.",
  "当前供应商的配置没有完整写入 Codex，请检查 Base URL 和 API Key。": "The current provider's config isn't fully written to Codex. Check its Base URL and API key.",
  "当前供应商还没填混入 API 的 Base URL / Key。": "The current provider has no Base URL / key for the mixed-in API yet.",
  "经聚合网关": "Via aggregate gateway",
  "聚合供应商会在多个成员间轮转，请在「连接与供应商」里逐个测试成员。": "An aggregate provider rotates across its members; test them one by one under Connection & providers.",
  "还没有供应商。添加一个，或在 Codex 里登录 ChatGPT。": "No provider yet. Add one, or sign in to ChatGPT inside Codex.",
  "配置 Codex 连接": "Set up Codex connection",
  "切换 Codex 的供应商与连接方式": "Switch Codex providers and how it connects",
  "调用次数、Token 与费用": "Calls, tokens and cost",
  "主题、更新、日志与诊断": "Theme, updates, logs and diagnostics",
