  "同时管理 Codex、Claude Code、Grok 等多个 Agent，经同一个网关共用供应商池。": "Manage Codex, Claude Code, Grok and more side by side, sharing one provider pool through the gateway.",
  "修改": "Change",
  "全部功能：同时管理 Codex、Claude Code、Grok 等多个 Agent。只用 Codex 或只用增强功能的话，可以切换模式隐藏用不到的内容。": "All features: manage Codex, Claude Code, Grok and more. If you only use Codex or only want the enhancements, switch modes to hide what you don't need.",
  "只用增强功能": "Enhancements only",
  "供应商由其他工具管理": "Providers managed by another tool",
  "Codex 概览": "Codex overview",
  // Agent 桌宠
  "试听": "Preview sound",
  "Agent 桌宠": "Agent pet",
  "桌宠类型": "Pet type",
  "二选一，同一时间只显示一个。": "Pick one; only one pet is shown at a time.",
  "简单桌宠": "Simple pet",
  "从图库挑一张图或用自己的图片，点一下压扁回弹，带按压音效。": "Pick a gallery image or your own; it squishes and bounces back when clicked, with press sounds.",
  "大肥鱼（DeepSeek 鲸鱼）": "Big fat fish (DeepSeek whale)",
  "原版鲸鱼用量挂件：余额、价格与用量统计、泡泡编辑器、音效库和提醒。": "The original whale usage widget: balance, price and usage statistics, bubble editor, sound library and alerts.",
  "大肥鱼预览暂不可用": "Whale preview is unavailable",
  "在 Codex 里可以拖动、缩放它，点角色旁的菜单配置泡泡、音效、提醒和用量统计。": "Drag and resize it in Codex; open the menu beside the character to configure bubbles, sounds, alerts and usage statistics.",
  "鲸鱼角色、完整界面引擎及内置音效 / 动图来自 MeteorNOX/DeepSeek-Balance-Whale-Widget（代码 MIT；素材按上游声明原样提供，不重新授权，也不声明为本项目原创）。": "The whale character, complete UI engine and built-in sounds/animations come from MeteorNOX/DeepSeek-Balance-Whale-Widget (code under MIT; media provided as-is per the upstream notice, not relicensed and not claimed as original work by this project).",
  "API 余额（可选）": "API balance (optional)",
  "跟随 Codex++ 当前供应商查询余额；Codex 订阅额度和本地 token 无需配置此项。": "Query the current Codex++ provider's balance. Codex subscription limits and local tokens work without this configuration.",
  "余额查询方式": "Balance source",
  "自动识别已支持的接口": "Recognize supported providers",
  "仅显示 Codex 用量": "Codex usage only",
  "自定义供应商余额接口": "Custom provider balance endpoint",
  "按供应商文档填写 GET 接口和返回字段，复用当前供应商的 API Key。币种和倍率应与供应商账单一致。": "Enter the GET endpoint and response field from your provider's documentation. Uses the current provider's API key. Currency and scale must match the provider's billing units.",
