  "每个请求换下一个 Key，用量更平均，但上游缓存命中会变低。": "Each request uses the next key. Usage is spread more evenly, but upstream cache hits drop.",
  "同一会话固定一个 Key，出错才换；保住上游的提示词缓存。": "A session keeps one key and only switches on errors, preserving the upstream prompt cache.",
  "会话粘性（推荐）": "Sticky sessions (recommended)",
