  "首次重试间隔": "First retry interval",
  "命中时退避重发。默认不选；常用 429（限流）和 5xx（服务端故障）。": "Matching responses are retried with backoff. None by default; 429 (rate limit) and 5xx (server errors) are common.",
  "始终由代理重试，但要等整段生成完才显示。": "The proxy always retries, but output appears only after the whole response is generated.",
  "旧版流式行为，仅在新版有问题时使用。": "Legacy streaming behavior; use only if the new one misbehaves.",
  "保留实时输出；正文出现前遇到过载由代理重试。": "Keeps live output; overloads before the body starts are retried by the proxy.",
  "首字提交延迟": "First-token commit delay",
  "出现正文后再缓冲的时长，0 表示立即提交。": "How long to buffer after the body starts; 0 commits immediately.",
  "注意：手填但没写进模型列表的模型也会被改写，请先把要用的模型都加进列表。": "Note: models typed manually but missing from the model list are rewritten too, so add every model you use to the list first.",
  "恢复默认": "Restore defaults",
  "Chat Completions / Anthropic 请求经本地服务器转成 Responses": "Chat Completions / Anthropic requests are converted to Responses by the local server",
  "当前供应商直连 Responses，不需要转换": "The current provider speaks Responses directly; no conversion needed",
  "默认成员的模型以裸名发布，其他成员带 cpx- 前缀；悬停已勾选的成员可「设为默认」。本模式不使用轮转策略或通配符路由。": "The default member's models are published by bare name; other members get a cpx- prefix. Hover a checked member to set it as default. This mode uses no rotation strategy or wildcard routes.",
  "使用 Codex 当前登录的 ChatGPT 账号": "Uses the ChatGPT account currently signed in to Codex",
