  "把选中会话的工作目录改到另一个文件夹；会先列出受影响的会话，确认后才执行。": "Change the working directory of the selected sessions to another folder. The affected sessions are listed first; nothing happens until you confirm.",
  "重新定位目录：项目文件夹挪了位置时，把这个目录下的全部会话改到新的文件夹": "Relocate folder: when the project folder has moved, point every session under this directory at the new folder",
  "选择要把会话移到的文件夹": "Choose the folder to move the sessions to",
