  "新目录": "New folder",
  "正在移动…": "Moving…",
  "会同时更新会话索引、侧边栏记录和会话文件里记录的工作目录，恢复会话时使用新目录；对话内容不变。改动前的记录会先备份。": "The session index, the sidebar records and the working directory recorded in the session files are updated together, so resuming a session uses the new folder. Conversation content is unchanged, and the previous records are backed up first.",
  "Codex 正在运行。请先完全退出 Codex，再点「重新检查」。": "Codex is running. Quit Codex completely, then click \"Check again\".",
