  "只统计经过 Codex++ 的请求（网关或协议转换）。直连时请求不经过 Codex++，这里不会有记录。": "Only requests that go through Codex++ (gateway or protocol conversion) are counted. Direct connections bypass Codex++ and won't show up here.",
