  "查询余额": "Check balances",
  "会联网查询网关供应商池里中转站和 DeepSeek 等厂商的余额。": "Queries balances online for relays and vendors such as DeepSeek in the gateway pool.",
  "余额查询失败，请稍后重试。": "Balance lookup failed. Try again later.",
  "Key 不限额度，在供应商详情里配置访问令牌后可显示账户余额": "This key has no quota limit. Configure an access token in the provider details to show the account balance.",
  "没有可以查询余额的供应商。": "No provider supports balance lookup.",
  "查询失败": "Lookup failed",
  "还没用上网关": "Gateway not in use yet",
  "网关把 Codex、Claude Code、Grok 接到同一个供应商池：一处管理 Key 和模型，在这里就能随时给每个 Agent 换模型。": "The gateway connects Codex, Claude Code and Grok to one provider pool: manage keys and models in one place, and switch each agent's model right here.",
  "了解网关": "About the gateway",
  "各 Agent 用的模型": "Model per agent",
  "面板里能看 Codex 状态、一键启动或重启、切换供应商、看用量，网关用户还能给各 Agent 换模型。右键仍是原来的菜单，双击打开主窗口；关掉恢复原来的点击行为。": "The panel shows Codex's status, starts or restarts it, switches providers and shows usage; gateway users can also switch each agent's model. Right-click still opens the menu and double-click opens the main window; turn off to restore the original click behavior.",
  "Codex 还指向网关托管的供应商": "Codex still points at the gateway-managed provider",
  "网关里没有 Codex 的接入记录（可能降级后又升级过，或网关状态文件损坏），请求可能连不上。点「切回直连」切回接入前或列表里第一个直连供应商。": "The gateway has no connection record for Codex (perhaps after a downgrade and upgrade, or a damaged gateway state file), so requests may fail. Use Switch back to direct to return to the provider used before, or the first direct provider in the list.",
  "切回直连": "Switch back to direct",
