  "要带 *": "Needs a *",
  "通配符按「供应商 id/模型」或模型名匹配，* 代表任意字符；上游新增的模型会自动算进来。": "Patterns match “provider id/model” or the model name, * standing for any characters; models the upstream adds later join automatically.",
  "额度": "Quota",
  "刷新额度": "Refresh quota",
  "剩余额度（取最紧的窗口）": "Quota left (tightest window)",
  "额度优先：订阅账号里剩余额度最多的先试；没有额度数据的排在后面，额度用完的排最后。": "Most quota first: the subscription with the most quota left goes first; ones without quota data come after, used-up ones last.",
  "速度优先：最近响应最快的先试；还没测过的先试一次，之后按实测速度排。": "Fastest first: the one that answered fastest lately goes first; untested ones are tried once, then ranked by measured speed.",
  "整个会话固定": "Whole conversation",
  "不固定": "Off",
  "缓存期内固定": "While cached",
  "同一会话一直先试上次回答的成员，它答不了才换，最省缓存。": "A conversation keeps trying the member that last answered first, moving only when it can't answer: the most cache saved.",
  "每个请求都按模式重新排，会话中途可能换成员，上游的提示词缓存会失效。": "Every request is ordered afresh, so a conversation can switch members midway and lose the upstream prompt cache.",
  "同一会话 10 分钟内继续先试上次回答的成员，保住上游的提示词缓存；空闲超过 10 分钟再按模式重新排。": "Within 10 minutes a conversation keeps trying the member that last answered first, keeping the upstream prompt cache; after 10 idle minutes it's ordered afresh.",
