  "按每个 Key 计；达到上限时先换别的 Key 或下一家，都满了就排队等待（最多 2 分钟）。": "Counted per key. When a key hits its limit, the gateway switches to another key or the next provider; when all are full, it queues (up to 2 minutes).",
