  "只保留非 MCP、插件的跨供应商配置；MCP&插件在独立页面管理。":
    "Keeps only cross-provider config that isn't MCP/Skills/Plugins; tools and plugins are managed on a separate page.",
  "可勾选 API 供应商或已完成 ChatGPT 登录的官方账号；聚合供应商不会作为成员。":
    "API providers or official accounts with a completed ChatGPT login can be selected; aggregate providers can't be members.",
  "使用已登录的 ChatGPT 账号凭据": "Uses the signed-in ChatGPT account credentials",
  "未填写：用 Codex 的官方模型目录": "Not set: uses Codex's official model directory",
  "可更新": "Update available",
  "同一对话保持一个成员，不同对话依次分配。": "Keeps one member per conversation; different conversations are assigned in turn.",
  "同步目标": "Sync target",
  "名称": "Name",
  "启动 Codex App 时追加到默认 CDP 参数后。留空则保持默认启动行为。":
    "Appended after the default CDP arguments when launching the Codex app. Leave empty to keep default launch behavior.",
  "启动 Codex": "Launch Codex",
  "启动任务": "Launch task",
  "启动前修复会话索引": "Repair session index before launch",
  "启动前检查会话数据库中缺失的消息投影并补齐；只增不改，不会改写会话归属。运行期间每 30 分钟复查索引。保存设置后生效。":
    "Scans the session database before launch and backfills missing message projections; append-only and never rewrites thread ownership. Re-checks the index every 30 minutes while running. Applies after saving settings.",
  "切换供应商时同步会话归属": "Sync thread ownership when switching providers",
  "启动前把历史会话的供应商归属批量改写到当前供应商，让不同供应商名下的会话归入当前列表。只改写归属，不删除会话。保存设置后生效。":
    "Rewrites the provider ownership of historical threads to the current provider before launch, so threads from other providers appear in the current list. Ownership only; no threads are deleted. Applies after saving settings.",
  "纯 API 模式禁用 Work 视图": "Disable Work view in Pure API mode",
  "Work 视图要求 ChatGPT 账号身份，纯 API Key 下发送消息会报 Work browser access requires an authenticated account。开启后每次启动 Codex 前把详情模式写回 Codex；重新启动 Codex 后生效。": "Work view requires a ChatGPT account identity; with a Pure API key, sending a message fails with \"Work browser access requires an authenticated account\". When enabled, the detail mode is switched back to Codex before each launch. Restart Codex to apply.",
  "自动审批模型": "Auto-review model",
  "留空则原样转发 codex-auto-review": "Leave empty to forward codex-auto-review unchanged",
  "Multi Agent 协议": "Multi-Agent protocol",
  "自动（推荐）": "Auto (recommended)",
  "v1（经典，转 Chat 中转适用）": "v1 (classic; use for Chat-completions relays)",
  "v2（新版，需上游支持加密载荷）": "v2 (new; requires an upstream that supports encrypted payloads)",
  "子代理协议的供应商级默认；模型元数据里的 multi_agent_version 声明优先于它。选 v1 会在使用该供应商期间压下 [features] multi_agent_v2，切走时自动还原。仅对直连供应商生效，Codex 经新版网关接入时由网关配置决定。仅新会话生效。":
    "Provider-level default for the sub-agent protocol; a per-model multi_agent_version declaration in model metadata takes precedence. Choosing v1 forces [features] multi_agent_v2 off only while this provider is active and restores it when you switch away. Direct providers only; when Codex connects through the new gateway this is decided by the gateway configuration. New sessions only.",
  "跟随供应商设置": "Follow provider setting",
  "v1（经典）": "v1 (classic)",
  "v2（新版）": "v2 (new)",
  "关闭子代理": "Disable sub-agents",
  "v2 需上游支持加密子代理载荷，转 Chat 协议的中转请选 v1；仅新会话生效。":
    "v2 requires an upstream that supports encrypted sub-agent payloads; pick v1 for Chat-completions relays. New sessions only.",
  "切换模型后旧会话跟随新默认": "Existing sessions follow the new default model",
  "切换供应商或默认模型后，下次启动前把仍停在旧默认模型的会话改为新默认；手动选过模型的会话不变。保存设置后生效。":
    "After switching provider or default model, sessions still on the previous default move to the new default before the next launch. Sessions with a manually chosen model are untouched. Takes effect after saving settings.",
  "启用": "Enable",
  "启用内置拓展": "Enable built-in extensions",
  "独立模式": "Standalone mode",
  "增强总开关关闭后仍会生效的补丁。":
    "Patches that still apply after the enhancement master switch is turned off.",
  "官方额度解锁": "Official quota unlock",
  "增强开启时此能力已自动生效；此开关只在关闭增强后生效。":
    "This capability is already active while enhancements are on; the switch only applies after enhancements are turned off.",
  "官方订阅额度耗尽后仍可发送，不区分供应商模式；纯官方登录发出的请求仍可能被官方拒绝。只改客户端发送状态，不改变真实用量与计费。重启 Codex 后生效。": "Keeps sending after the official subscription quota runs out, regardless of provider mode; requests from plain official login may still be rejected by OpenAI. Only changes the client send state, not real usage or billing. Takes effect after restarting Codex.",
  "启用供应商配置切换": "Enable provider configuration switching",
  "包含上下文大小与压缩阈值；留空即沿用全局默认值。":
    "Covers context size and compaction threshold; leave blank to keep the global defaults.",
  "图片": "Image",
  "在会话列表悬停显示删除按钮，并支持撤销。": "Show a delete button on hover in the session list, with undo support.",
  "删除会话时不再确认": "Delete sessions without confirmation",
  "开启后删除本机会话不再弹出确认框，删除后仍可在提示里撤销。远端 / SSH 会话无法撤销，仍会要求确认。":
    "When on, deleting a local session skips the confirmation dialog; you can still undo from the notice. Remote / SSH sessions cannot be undone and still ask for confirmation.",
  "在会话列表显示导出按钮，导出带时间戳的 Markdown。": "Show an export button in the session list to export timestamped Markdown.",
  "在侧边栏会话标题前显示短 ID 和 UUIDv7 创建时间，方便定位历史会话。":
    "Show a short ID and UUIDv7 creation time before session titles in the sidebar to help locate past sessions.",
