  "Statsig 界面增强": "Statsig UI enhancements",
  "按上报用量判断压缩（实验）": "Use reported usage for compaction (experimental)",
  "仅对 Codex App 和 CLI 中已经经过本地代理的请求生效，按上报用量判断压缩，不改 usage，也不自动启用代理。开关变更在下一次响应后生效；旧会话首次响应前仍可能按原估算触发压缩。": "Only applies to Codex App and CLI requests already routed through the local proxy. Uses reported usage for compaction without changing usage or enabling the proxy. Switch changes take effect after the next response; older conversations may still compact from the original estimate before their first response.",
  "强制打开几项界面侧的远程开关：隐藏升级与额度推销提示、放宽网络重试与流式超时、补开记忆、消息队列、会话时间线、侧聊 attach 与会话内权限刷新。每个开关都能在 Codex++ 设置的 Feature Lab →「Statsig 开关」里单独改，也能记录页面查询过的其他开关。只影响本机界面与超时参数，云端能力与配额不受影响；关闭后重新启动 Codex 生效。": "Force a few client-side remote switches: hide upgrade and quota upsells, relax network retry and streaming timeouts, and turn on the Statsig switches for memories, the follow-up queue, thread timeline, side-chat attach and in-thread permission refresh. Each switch can be changed individually under Feature Lab → \"Statsig switches\" in Codex++ settings, which can also record other switches the page queries. Only local UI and timeout values change; cloud capabilities and quotas are unaffected. Restart Codex after turning this off.",
  "强制启用 Codex App 内置 zh-CN 语言包，避免 Statsig/VPN 不通时回退英文。需重启 Codex 才能完整生效。": "Force the built-in zh-CN locale pack in the Codex app so the UI does not fall back to English when Statsig or the VPN is unreachable. Fully applies after restarting Codex.",
  "容量错误自动重试": "Auto-retry on capacity errors",
  "模型容量不足（Selected model is at capacity）时自动点「重试」。Codex 原生只会自动重试 4 次且带 10/30/120/300 秒倒计时，之后只剩手动按钮；开启后由 Codex++ 立刻接管，原生倒计时也不等。": "Automatically clicks Retry when the selected model is at capacity. Codex only auto-retries four times on its own, spaced by a 10/30/120/300 second countdown, and then leaves a manual button; when enabled, Codex++ takes over immediately without waiting for that countdown.",
  "索引": "Index",
  "纯 API": "Pure API",
  "纯文本模型请配置此项": "Configure this for text-only models",
  "纯 API 模式": "Pure API mode",
  "官方登录未混入 API 时不写入会话 provider": "Official login without mixed API does not write a session provider",
  "Custom（默认）": "Custom (default)",
  "OpenAI（兼容 ChatGPT Remote）": "OpenAI (ChatGPT Remote compatible)",
  "选择 OpenAI 后，Codex Remote 会把当前会话识别为 ChatGPT 会话；中转仍使用 custom 表。":
    "OpenAI makes Codex Remote identify the session as a ChatGPT session; the relay still uses the custom table.",
  "OpenAI 会话身份需要 Responses API；Chat Completions 不支持远程压缩。":
    "OpenAI session identity requires the Responses API; Chat Completions does not support remote compaction.",
  "聚合请求仍由本地 Responses 代理轮转成员；OpenAI 身份用于让 ChatGPT Remote 识别会话。":
    "Aggregate requests still rotate members through the local Responses proxy; OpenAI identity lets ChatGPT Remote recognize the session.",
  "OpenAI 会话身份仅支持 Responses API；Chat Completions 不支持 ChatGPT Remote 的远程压缩。请切换协议或改回 Custom。":
    "OpenAI session identity only supports the Responses API; Chat Completions does not support ChatGPT Remote remote compaction. Switch protocol or return to Custom.",
  "编辑": "Edit",
  "编辑后保存列表，再切换模式时会使用新配置": "After editing, save the list; the new config is used the next time you switch modes",
  "缺失": "Missing",
  "聚合": "Aggregate",
  "聚合/中转": "Aggregate/relay",
  "聚合供应商": "Aggregate provider",
  "聚合供应商会在真实对话中轮转成员，请测试成员供应商": "Aggregate providers rotate members in real conversations; test the member providers instead",
  "聚合供应商只保存成员和策略配置，成员来自已有 API 供应商；切为当前后会通过本地协议代理轮转请求。":
    "Aggregate providers only store member and strategy config drawn from existing API providers; once active, requests rotate through the local protocol proxy.",
  "此聚合会把成员模型合并到 Codex 列表；带供应商前缀的模型固定发送到对应成员，普通模型仍按策略轮转。":
    "This aggregate merges member models into the Codex list; prefixed models stay bound to their member, while plain model names still follow the strategy.",
  "聚合供应商至少需要勾选 1 个可用成员（API 供应商或官方登录账号）。":
    "An aggregate provider needs at least 1 usable member (an API provider or a signed-in official account).",
  "把默认成员的官方登录同步到 Codex":
    "Sync the default member's official login into Codex",
  "开启后切换到本聚合时，会把默认成员的 ChatGPT 凭据一并写进 Codex（代理 Key 保留），账号在 Codex 里就是登录态。默认成员不是官方登录时无效。":
    "When enabled, switching to this aggregate also writes the default member's ChatGPT credentials into Codex (the proxy key is kept), so the account shows as signed in. No effect when the default member is not an official login.",
  "当前默认成员不是官方登录账号，无法把登录同步到 Codex；只有「官方登录」类型的成员才有 ChatGPT 凭据。":
    "The current default member is not an official-login account, so its login cannot be synced into Codex; only official-login members carry ChatGPT credentials.",
  "聚合策略": "Aggregate strategy",
  "故障转移": "Failover",
  "模型聚合": "Model aggregation",
  "先选择类型": "Choose a type first",
  "故障转移与模型聚合彼此独立；选择后只显示对应的成员和路由表单。": "Failover and model aggregation are independent; only the matching member and routing form appears after selection.",
  "多个供应商组成请求池，支持失败切换、会话轮转、请求轮转和权重。": "Pool providers for failover, conversation rotation, request rotation and weights.",
  "故障转移：按策略分配请求": "Failover: requests are distributed by strategy",
  "模型聚合：模型固定绑定供应商": "Model aggregation: models stay bound to their provider",
