  "正在读取社区拓展…": "Loading community extensions…",
  "没有声明任何能力。": "It declares no capabilities.",
  "社区拓展已关闭，不会访问 GitHub。": "Community extensions are off; GitHub is not contacted.",
  "社区拓展排序": "Sort community extensions",
  "社区拓展未经 Codex++ 审核": "Community extensions are not reviewed by Codex++",
  "还没有社区拓展。给仓库加上 codexpp-extension 标签即可出现在这里。": "No community extensions yet. Add the codexpp-extension topic to a repository to list it here.",
  "这里列出 GitHub 上打了 codexpp-extension 标签的拓展包仓库。作者可以在新版本里加入任意代码，只安装你信任的作者的拓展。安装时锁定到作者发布的版本，并在安装前列出它要的权限。": "Extension repositories on GitHub with the codexpp-extension topic. Authors can add any code in a new version, so only install extensions from authors you trust. Installs are pinned to the version the author released, and the permissions are listed before installing.",
