  "预览展示配置文件原文差异，密钥等敏感值也一并可见。": "The preview shows raw configuration diffs, including sensitive values such as keys.",
  "断开还会更新 Codex++ 的绑定、供应商记录与恢复存档，这些内部状态不在配置 diff 中。": "Disconnecting also updates Codex++ bindings, provider records and restoration archives. These internal changes are not included in the configuration diff.",
  "该 Agent 没有可用的断开适配器。": "This agent has no available disconnect adapter.",
  "配置仍指向网关，但恢复存档缺失或损坏；未提供不完整的断开预览。": "The configuration still points to the gateway, but its restoration archive is missing or damaged. An incomplete disconnect preview is not provided.",
  "配置已由其他工具改走；断开只清理网关记录，不覆盖当前配置。": "Another tool has redirected the configuration. Disconnecting only clears gateway records and leaves the current configuration unchanged.",
  "恢复存档无法与当前配置安全合并；请先检查配置语法后重新预览。": "The restoration archive cannot be safely merged with the current configuration. Check the configuration syntax and refresh the preview.",
  "网关状态无法读取；无法在隔离环境中精确预演此次还原。": "The gateway state cannot be read, so this restoration cannot be accurately simulated in isolation.",
  "Grok 仍连接网关，但没有可用的恢复存档，当前供应商也没有模型；请在 Grok 供应商页添加并应用一个直连供应商后再断开。": "Grok still points to the gateway, but no usable restoration archive or direct-provider models are available. Add and apply a direct provider on the Grok providers page before disconnecting.",
    "隔离预演未能完成还原；原配置未被修改，请检查可切回的供应商和恢复存档。": "The isolated restoration simulation did not complete. The original configuration was not changed. Check the available direct providers and restoration archive.",
  "Codex 配置按实时恢复存档计算；正式断开仍需成功切换直连供应商，并更新模型目录、应用状态和备份。供应商校验或写入失败时会中止断开。": "The Codex configuration is calculated from the live restoration archive. Disconnecting still requires switching to the direct provider and updating model catalogs, application state and backups. The disconnect is aborted if provider validation or writing fails.",
  // cx-pages:agents —— 补丁 Desktop（Claude 副本页）与完整功能模式的小改
  "补丁 Desktop": "Patched Desktop",
  "制作、更新与启动改过代码的 Desktop 副本；原件与 app.asar 不动": "Create, update and launch a modified Desktop copy; the original app and its app.asar stay untouched",
  "上下文窗口 未声明（Claude 按 200k）": "Context window undeclared (Claude assumes 200k)",
  "取消信任证书": "Remove certificate trust",
  "列出全部模型": "List every model",
  "默认只列窗口不小于默认模型的模型（Claude 的窗口是启动时一份全局值，切到更小的模型不会跟着变小）；打开后池里的聊天模型全列出来，代价是切到小窗口模型可能超上限。": "By default only models whose context window is at least the default model's are listed (Claude takes one global window at start-up, and switching to a smaller model does not shrink it); turn this on to list every chat model in the pool, at the cost of risking an overflow after switching to one with a smaller window.",
  "隐藏无供应商的模型": "Hide models without a provider",
  "Claude 自带的 Opus、Sonnet、Haiku 等条目不对应任何供应商，选了也会被换成默认模型。打开后选择器里只留供应商池里的模型；改完需要重新启动本地服务。": "Claude's built-in entries such as Opus, Sonnet and Haiku map to no provider, so picking one silently falls back to the default model. Turn this on to show only models from the provider pool; restart the local service after changing it.",
  "等": " and others",
  // cx-pages:agents —— Claude 本地模式：模型入口搬到「Agent 接入」、侧栏 / 行内的启动键
  "模型在「Agent 接入」里的 Claude Desktop 行选择，改完需要重新启动本地服务。": "The model is chosen on the Claude Desktop row under Agent connections; restart the local service after changing it.",
