  "网关端口已保存": "Gateway port saved",
  "完全退出 Codex++（含托盘）后重新打开生效；走网关的 Agent 会在启动时改到新端口，没跟上的在「Agent 接入」里重新接入一次。": "Takes effect after fully quitting Codex++ (including the tray) and reopening it. Agents on the gateway switch to the new port at startup; reconnect any that don't under Agent access.",
  "待重启": "Restart pending",
  "Agent 配置里写的是这个端口。保存时会检测端口是否被占用；旧端口会被记住，旧配置里的地址仍认作 Codex++ 的地址。": "Agent configs point at this port. Saving checks whether the port is in use; old ports are remembered so addresses in old configs are still recognized as Codex++'s.",

