  "核实上次操作": "Check previous operation",
  "消耗一张重置卡，重置账号额度": "Use one reset voucher to reset account quota",
  "已用、已失效或状态未知": "Used, expired, or status unknown",
  "放弃上次重置操作": "Abandon previous reset operation",
  "放弃并重新开始": "Abandon and start over",
  "放弃上次未确认的重置操作，下次使用发起新的请求": "Abandon the unconfirmed reset operation; the next use sends a new request",
  "放弃后，上次未确认的重置操作不再重试，下次使用会发起新的请求。若上次其实已经生效，可能会再扣一张重置卡。建议先刷新额度确认上次是否已重置。": "After abandoning, the unconfirmed reset operation will not be retried and the next use sends a new request. If the previous attempt actually went through, another voucher may be used. Refresh the quota first to check whether it was reset.",
  // Claude 增强生效方式（完整功能模式 / 补丁副本）与页面扩展
  "完整功能模式": "Full local mode",
  "补丁副本": "Patched copy",
  "补丁副本没在用": "The patched copy is not in use",
  "现在的生效方式是完整功能模式：汉化、听写、页面扩展由本地服务注入官方 Claude，用不到补丁版。要改用补丁版，先把生效方式换过来。": "Enhancements currently apply through the full local mode: localization, dictation and page extensions are injected into the official Claude by the local service, so the patched copy is not used. Switch how enhancements apply to use the patched copy.",
  "改用补丁副本": "Use the patched copy",
  "改 Claude Code 里 Bash 的默认等待和最长等待时间，重新启动 Claude 后生效。": "Change the default and maximum Bash wait times in Claude Code; takes effect after restarting Claude.",
  "Cowork 的 Bash 时限": "Cowork Bash timeout",
  "Cowork 的 Bash 时限写在 Claude 主进程代码里，只有补丁副本能在启动时改；完整功能模式下保持 Claude 原生时限。": "The Cowork Bash timeout lives in Claude's main-process code, which only the patched copy can change at launch; the full local mode keeps Claude's native timeout.",
