  "DeepSeek、Kimi、智谱这些 OpenAI 协议的也能用，网关会自动转换。": "OpenAI-protocol providers such as DeepSeek, Kimi and Zhipu work too; the gateway converts requests automatically.",
  "CC Switch 里的 Claude 供应商": "Claude providers in CC Switch",
  "Claude 启动后默认用这个模型；下面打开的供应商，它们的聊天模型都会列进 Claude 的模型选择器。": "Claude starts with this model; chat models from the providers switched on below are listed in Claude's model picker.",
  "从 CC Switch、ClaudeMom 或直连模式导入": "Import from CC Switch, ClaudeMom or direct mode",
  "ClaudeMom 的上游，Anthropic 协议": "ClaudeMom upstream, Anthropic protocol",
