  "到 Desktop 增强页启动补丁版": "Launch the patched copy from Desktop Enhancements",
  "启动模式": "Launch mode",
  "设置已保存，完全退出 Claude 后重新启动。": "Settings saved. Fully quit Claude and start it again.",
  "制作副本并启动补丁版": "Build the copy and launch it",
  "启动改过代码的副本，汉化、听写、页面扩展在副本里注入；官方 Claude 不动。": "Launches the modified copy; localization, dictation and page extensions are injected there and the official Claude stays untouched.",
  "经本地服务启动官方 Claude，汉化、听写、页面扩展都由它注入。已打开的 Claude 需完全退出重开。": "Launches the official Claude through the local service, which injects localization, dictation and page extensions. Fully quit an open Claude and reopen it.",
  "用安装包自带的界面直连网关，不注入汉化、听写和页面扩展。已打开的 Claude 需完全退出重开。": "Uses the interface bundled with the app and connects to the gateway directly, without localization, dictation or page extensions. Fully quit an open Claude and reopen it.",
  "往 Claude 页面里加 js / css 的页面扩展，格式和扩展市场与 ClaudeMom 相同；也能给 Claude Code 装适配它的 Codex++ 拓展。": "Page extensions add JS / CSS to Claude's pages, with the same format and market as ClaudeMom; Codex++ extensions made for Claude Code can be installed too.",
