  "追加任务或问题": "Follow-up task or question",
  "选择可调用的 CLI 与默认模型。CLI 路径留空时自动查找已安装的程序。路径检测只确认 CLI 文件存在，登录状态在执行任务时验证。": "Choose which CLIs can be called and their default models. With an empty path, the installed program is found automatically. The path check only confirms the file exists; sign-in is checked when a task runs.",
