  "Codex++ 把 ChatGPT.app 里现成的 Computer Use 与 Chrome 扩展，通过 MCP 转给其它 AI 客户端。左边点「接入」；操作方式、审批与悬浮预览在图下方设置。": "Codex++ passes the Computer Use and Chrome extension built into ChatGPT.app to other AI clients over MCP. Click Connect on the left; the operating mode, approvals and floating preview are set below the diagram.",
