  "只给 Codex++ 自己维护的拓展用；审核通过的第三方拓展显示为「精选」": "Only for extensions Codex++ maintains itself; approved third-party extensions show as Curated",
  "同 Codex 的画中画：在屏幕右上角实时显示目标窗口；回合结束或空闲 20 秒自动收起。需要屏幕录制权限。": "Like Codex's picture-in-picture: shows the target window live in the top-right corner of the screen and hides when the turn ends or after 20 idle seconds. Needs screen recording permission.",
  "名称（可选）": "Name (optional)",
  "启动中…": "Starting…",
  "和 Codex 一样，把许可请求转给当前连接的客户端弹卡确认；拒绝即不放行。": "Like Codex: the connected client shows a card to confirm each permission request; declining blocks it.",
  "和 Codex 一样，用 cua_repl 的 js 工具操作桌面与 Chrome；首次使用会自动下发完整说明与确认规则，支持 paste 输入中文。": "Like Codex: operates the desktop and Chrome through cua_repl's js tool. The first use sends the full instructions and confirmation rules, and paste can type Chinese text.",
