  "安装扩展": "Install extension",
  "完整差异": "Full diff",
  "实时看 Codex 正在操作的目标窗口。画面由 Codex++ 自己抓取，和官方窗口镜像同源，只是不经官方通道。": "Watch the window Codex is operating, live. Codex++ captures the picture itself from the same source as the official window mirror, just not through the official channel.",
  "实际跑一次 MCP 握手并调用 sky.list_apps()，确认工具链可用。": "Runs a real MCP handshake and calls sky.list_apps() to confirm the toolchain works.",
  "审批策略": "Approval policy",
  "审批策略已保存。": "Approval policy saved.",
  "审批记录": "Approval records",
  "审核拓展": "Review extension",
  "客户端改用了别的配置目录时（例如被包装器设置了 CLAUDE_CONFIG_DIR），上面的默认路径它读不到。在这里登记它实际读取的目录，可添加任意多个；也可以直接填配置文件路径。": "When a client uses another config folder (for example a wrapper set CLAUDE_CONFIG_DIR), it can't read the default paths above. Register the folder it actually reads here; add as many as you need, or enter the config file path directly.",
  "客户端类型": "Client type",
