  "开始预览失败。": "Could not start the preview.",
  "弹卡确认": "Ask with a card",
  "弹卡确认同 Codex：由当前连接的客户端（Claude Code、Codex 等）弹卡，拒绝即不放行，勾「始终允许」后这个应用以后不再问；客户端不支持弹卡时退回自动放行。自动放行：不询问，只记审计日志。": "Ask with a card works like Codex: the connected client (Claude Code, Codex and so on) shows a card; declining blocks the app, and with Always allow checked the app isn't asked about again. Clients that can't show cards fall back to Allow automatically. Allow automatically never asks and only writes an audit log.",
  "当前客户端不支持审批卡（elicitation）": "The current client doesn't support approval cards (elicitation)",
  "悬浮预览": "Floating preview",
