  "打开 ChatGPT.app 失败。": "Could not open ChatGPT.app.",
  "扩展已安装": "Extension installed",
  "抓取方式": "Capture method",
  "拒绝": "Denied",
  "授权失败。": "Authorization failed.",
  "接入后重启对应客户端。JS 方式下桌面与浏览器都用 mcp__codex-plus-cu__js，codex-plus-browser 不提供工具。": "Restart the client after connecting. In JS mode, both the desktop and the browser use mcp__codex-plus-cu__js, and codex-plus-browser provides no tools.",
  "接入后重启对应客户端，工具名以 mcp__codex-plus-cu__ 与 mcp__codex-plus-browser__ 开头。": "Restart the client after connecting. Tool names start with mcp__codex-plus-cu__ and mcp__codex-plus-browser__.",
  "推荐 JS：与 Codex 当前的用法一致，桌面和 Chrome 都在同一个 js 工具里；首次使用自带完整说明和确认规则；一次调用能连续做多步操作，更快、更省 token；能用 paste 输入中文和多行文字。": "JS is recommended: it matches how Codex works today, with the desktop and Chrome in one js tool; the first use brings full instructions and confirmation rules; one call can chain several steps, which is faster and uses fewer tokens; and paste can type Chinese and multi-line text.",
  "提示词组装 → 网关": "Prompt assembly → gateway",
  "撤销": "Revoke",
